from typing import Callable, Iterable, TypeVar, Optional

T = TypeVar('T')


def filter_items(predicate: Callable[[T], bool]) -> Callable[[Iterable[T]], Iterable[T]]:
    """Create a filter operation that can be composed with other operations."""
    def apply(items: Iterable[T]) -> Iterable[T]:
        return (item for item in items if predicate(item))
    return apply


def transform_items(func: Callable[[T], T]) -> Callable[[Iterable[T]], Iterable[T]]:
    """Create a transform operation that can be composed with other operations."""
    def apply(items: Iterable[T]) -> Iterable[T]:
        return (func(item) for item in items)
    return apply


def pipeline(*operations: Callable[[Iterable], Iterable]) -> Callable[[Iterable], Iterable]:
    """Compose multiple operations into a single pipeline."""
    def apply(items):
        result = items
        for op in operations:
            result = op(result)
        return result
    return apply


def collect(items: Iterable[T]) -> list[T]:
    """Materialize an iterable into a list."""
    return list(items)

