from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable, Sequence


class DataProcessor(ABC):
    @abstractmethod
    def process(self, data: list[Any]) -> list[Any]:
        pass

    def __rshift__(self, other: DataProcessor) -> Pipeline:
        """Chain two processors with >> operator."""
        return Pipeline([self, other])


class PassthroughProcessor(DataProcessor):
    def process(self, data: list[Any]) -> list[Any]:
        return list(data)


class FilterProcessor(DataProcessor):
    def __init__(self, predicate: Callable[[Any], bool]) -> None:
        self.predicate = predicate

    def process(self, data: list[Any]) -> list[Any]:
        return [item for item in data if self.predicate(item)]


class TransformProcessor(DataProcessor):
    _MISSING = object()

    def __init__(self, transform_fn: Callable[[Any], Any]) -> None:
        self.transform_fn = transform_fn
        self._cache: dict[Any, Any] = {}

    def process(self, data: list[Any]) -> list[Any]:
        return [self._cached_transform(item) for item in data]

    def _cached_transform(self, item: Any) -> Any:
        try:
            cached = self._cache.get(item, self._MISSING)
            if cached is not self._MISSING:
                return cached
            result = self.transform_fn(item)
            self._cache[item] = result
            return result
        except TypeError:
            return self.transform_fn(item)

    def clear_cache(self) -> None:
        self._cache.clear()


class Pipeline(DataProcessor):
    def __init__(self, steps: Sequence[DataProcessor] = ()) -> None:
        self.steps: list[DataProcessor] = list(steps)

    def process(self, data: list[Any]) -> list[Any]:
        result = data
        for step in self.steps:
            result = step.process(result)
        return result

    def __rshift__(self, other: DataProcessor) -> Pipeline:
        if isinstance(other, Pipeline):
            return Pipeline([*self.steps, *other.steps])
        return Pipeline([*self.steps, other])


def build_pipeline(config: dict[str, Any]) -> Pipeline:
    """Build a pipeline from a config dict with optional 'filter' and 'transform' keys."""
    steps: list[DataProcessor] = []
    if config.get("filter"):
        steps.append(FilterProcessor(config["filter"]))
    if config.get("transform"):
        steps.append(TransformProcessor(config["transform"]))
    return Pipeline(steps or [PassthroughProcessor()])

